/**
 * Generic "what file is the workspace loader currently importing, and what is
 * its own on-disk text" context for `elementum build`'s own-file-child loader.
 *
 * Entity-agnostic on purpose: `engine/` may not import from `entities/`
 * (`__tests__/engine/no-entity-types-in-engine.test.ts`), so this exists
 * purely as plumbing — it knows nothing about automations or any other
 * entity kind. An entity module (e.g. `entities/automation/script-code.ts`)
 * that needs the file's real text — a `toString()` on a loaded function
 * returns source with every type annotation blanked out by Node's type
 * stripping — imports {@link currentSourceText} from here (entities/
 * importing engine/ is the normal direction; only the reverse is forbidden).
 *
 * State lives on `globalThis` (via a `Symbol.for` registry key), not a plain
 * module-scoped variable, for two independent reasons:
 *  - `AsyncLocalStorage` was tried first and rejected: the continuation
 *    context did not reliably reach the imported module's top-level code
 *    (confirmed empirically — that version silently lost context there).
 *  - A plain module-scoped variable has a SEPARATE failure mode: the same
 *    module can be instantiated twice in one process whenever something
 *    other than plain Node also loads it — Vitest's module runner is the
 *    live example, since the workspace loader is externalized and the test
 *    file's own imports are not. Writes through one copy are invisible to
 *    reads through the other. `globalThis` is the one thing guaranteed
 *    shared across however many separate module instances end up loaded in
 *    the same process.
 *
 * `elementum build`'s own-file-child loader still imports one file at a time
 * in a sequential loop (never concurrently) — see `discoverOwnFileChildren`
 * in `build.ts`. Do not parallelize that loop without revisiting this.
 */
export interface SourceTextContext {
    readonly filePath: string;
    readonly text: string;
}
/**
 * Run `fn` (a workspace module import) with `filePath`'s own text available via
 * {@link currentSourceText} for the duration of the returned promise.
 */
export declare function withSourceText<T>(filePath: string, text: string, fn: () => Promise<T>): Promise<T>;
/** The file/text currently being imported via {@link withSourceText}, or undefined outside that context. */
export declare function currentSourceText(): SourceTextContext | undefined;
